Here we can optimize it in such a way that, while multiplying, if the answer has already exceeded M, we can simply know that that mid isn't the answer. This tiny bit helps us reduce complexity and prevent overflows.

## Solution
```cpp[]
class Solution {
   public:
    int customPow(int x, int y, int z) {
        long long res = 1;
        for (int i = 0; i < y; i++) {
            res *= 1ll * x;
            if (res > (long long)z) return 1;
        }
        if (res == (long long)z) return 0;
        if (res > (long long)z) return 1;
        if (res < (long long)z) return -1;
    }

    int NthRoot(int N, int M) {
        int low = 1;
        int high = M;

        while (low <= high) {
            int mid = low + (high - low) / 2;

            int mul = customPow(mid, N, M);

            if (mul == 0) {
                return mid;
            } else if (mul == 1) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return -1;
    }
};

```

